// ClusterID implements device.Declaration: the cluster declared.
func (Declare) ClusterID() uint32 { return ClusterID }

// ClusterDeclaration implements device.Declaration: the declaration in
// the form the device kit applies it.
func (d Declare) ClusterDeclaration() spec.ClusterDeclaration {
	decl := spec.ClusterDeclaration{Cluster: ClusterID, Initial: d.Initial.AttributeValues(), Server: d.HostServer, Ports: d}
	if d.OnWrite != nil {
		decl.Attach = d.attach
	}
	decl.Features, decl.HasFeatures = uint32(d.Features), d.Features != 0 || d.NoFeatures
	decl.Elements.Commands = append(decl.Elements.Commands, d.Commands...)
	decl.Elements.Events = append(decl.Elements.Events, d.Events...)
	if d.HandleSetUtcTime != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetUtcTime)
		decl.Attach = d.attach
	}
	if d.HandleSetTrustedTimeSource != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetTrustedTimeSource)
		decl.Attach = d.attach
	}
	if d.HandleSetTimeZone != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetTimeZone)
		decl.Attach = d.attach
	}
	if d.HandleSetDstOffset != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetDstOffset)
		decl.Attach = d.attach
	}
	if d.HandleSetDefaultNtp != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetDefaultNtp)
		decl.Attach = d.attach
	}
	if d.NoFeatures && d.Features != 0 {
		decl.Attach = func(contract.ClusterServer) error {
			return errors.New(Name + ": Declare sets both NoFeatures and Features")
		}
	}
	return decl
}

// attach installs the declaration's veto and handlers on srv; the
// error names each one the server refused.
func (d Declare) attach(srv contract.ClusterServer) error {
	s := Wrap(srv)
	var errs []error
	if d.OnWrite != nil {
		errs = append(errs, spec.HookError(Name, "OnWrite", s.OnWrite(d.OnWrite)))
	}
	if d.HandleSetUtcTime != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetUtcTime", s.HandleSetUtcTime(d.HandleSetUtcTime)))
	}
	if d.HandleSetTrustedTimeSource != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetTrustedTimeSource", s.HandleSetTrustedTimeSource(d.HandleSetTrustedTimeSource)))
	}
	if d.HandleSetTimeZone != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetTimeZone", s.HandleSetTimeZone(d.HandleSetTimeZone)))
	}
	if d.HandleSetDstOffset != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetDstOffset", s.HandleSetDstOffset(d.HandleSetDstOffset)))
	}
	if d.HandleSetDefaultNtp != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetDefaultNtp", s.HandleSetDefaultNtp(d.HandleSetDefaultNtp)))
	}
	return errors.Join(errs...)
}
